/// - k2: real[1] (passed a plain number)
/// - returns m0: real[1][3] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn sun_spin_deruiter(b: [f64; 3], w: [f64; 3], s: [f64; 3], eclipse: bool, j: [[f64; 3]; 3], spin_dps: f64, k: f64, k1: f64, k2: f64) -> [f64; 3] {
    let mut m0: [f64; 3] = [0.0; 3];
    m0 = [0.0; 3];
    if (!eclipse) {
        let mut ws: f64 = rt::fabs((spin_dps * (core::f64::consts::PI / 180.0)));
        let mut sg: f64 = rt::sign(w[2]);
        if (sg == 0.0) {
            sg = 1.0;
        }
        let mut h: [f64; 3] = rt::mv(j, w);
        let mut ehz: f64 = (h[2] - ((sg * j[2][2]) * ws));
        let mut x: [f64; 3] = [0.0; 3];
        {
            let __end103: i64 = 3;
            let mut i: i64 = 0;
            while i < __end103 {
                x[(i) as usize] = (h[(i) as usize] + (((sg * j[2][2]) * ws) * s[(i) as usize]));
                i += 1;
            }
        }
        x[2] = (x[2] + (k1 * ehz));
        x[0] = (x[0] + (k2 * w[0]));
        x[1] = (x[1] + (k2 * w[1]));
        let mut aa: [f64; 3] = rt::cross(b, x);
        let mut bs: f64 = rt::dot(b, b);
        if (bs >= 1.0e-18) {
            {
                let __end104: i64 = 3;
                let mut i: i64 = 0;
                while i < __end104 {
                    m0[(i) as usize] = (((-(k)) * aa[(i) as usize]) / bs);
                    i += 1;
                }
            }
        }
    }
    m0
}
